    out = [row[:] for row in grid]

    # Find the solid marker stripe (color 2).
    axis = pos = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            axis, pos = "row", r
            break
    if axis is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                axis, pos = "col", c
                break
    if axis is None:
        return out

    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != background and grid[r][c] != 2]
    if not obj:
        return out

    dr = dc = 0
    if axis == "row":
        rmin = min(r for r, c in obj)
        rmax = max(r for r, c in obj)
        if pos < rmin:           # Move upward toward the stripe.
            dr = pos + 1 - rmin
        else:                    # Move downward toward the stripe.
            dr = pos - 1 - rmax
    else:
        cmin = min(c for r, c in obj)
        cmax = max(c for r, c in obj)
        if pos < cmin:           # Move left toward the stripe.
            dc = pos + 1 - cmin
        else:                    # Move right toward the stripe.
            dc = pos - 1 - cmax

    moved = [(r + dr, c + dc) for r, c in obj]
    for r, c in obj:
        out[r][c] = background
    for r, c in moved:
        out[r][c] = grid[r - dr][c - dc]

    if axis == "row":
        line = max(r for r, c in moved) + 1 if pos < min(r for r, c in moved) else min(r for r, c in moved) - 1
        if 0 <= line < h:
            out[line] = [8] * w
    else:
        line = max(c for r, c in moved) + 1 if pos < min(c for r, c in moved) else min(c for r, c in moved) - 1
        if 0 <= line < w:
            for r in range(h):
                out[r][line] = 8
    return out
